    },
    filterVehicles() {
      this.vehiclesToShow = 10;
      let finaltext = this.search.split(' ').join('');
      let squery = this.search.toLowerCase();
      if (finaltext.length > 0) {
        this.filteredVehicles = this.vehicles.filter((vehicle) => vehicle.model.toLowerCase().includes(squery)).sort();
