<template>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.3/css/all.min.css"
        referrerpolicy="no-referrer"/>
  <div class="panel">
    <div class="onlinePlayers">{{onlinePlayers}}<span class="onlineDot"> </span></div>
    <div class="currentLobby"><span class="item">LID:</span> {{lobbyID}}</div>
    <div class="timeDate"><i class="far fa-clock"></i>{{time}} {{date}}</div>
    <img src="../../assets/logo.png" alt="logo" class="logo">
  </div>
</template>

<script>
export default {
  name: "TopRightInfo",
  data() {
    return {
      time: '',
      date: '',
      timer: null,
      onlinePlayers: 15,
      lobbyID: 5,
    }
  },
  methods: {
    startClock() {
      this.updateClock();
      this.timer = setInterval(this.updateClock, 60000);
    },
    zeroPadding(num, digit) {
      let zero = '';
      for(let i = 0; i < digit; i++) {
        zero += '0';
      }
      return (zero + num).slice(-digit);
    },
    updateClock() {
      let cd = new Date();
      this.time = this.zeroPadding(cd.getHours(), 2) + ':' + this.zeroPadding(cd.getMinutes(), 2); // + ':' + this.zeroPadding(cd.getSeconds(), 2)
      this.date = this.zeroPadding(cd.getMonth()+1, 2) + '.' + this.zeroPadding(cd.getDate(), 2) + '.' + this.zeroPadding(cd.getFullYear(), 4);
    }
  },
  mounted() {
    this.startClock()
  }
}
</script>

<style scoped lang="scss">

.panel {
  padding: 5px 15px;
  height: 35px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 10px;
  color: rgba(241, 241, 241, 0.7);
  font-size: 15px;
  background: linear-gradient(130deg, transparent 20px, rgba($sago-darkest, 0.5) 20px);
  font-family: 'Nunito', sans-serif;
  font-weight: bold;


  .onlinePlayers {
    margin: 0px 20px;
    display: flex;
    justify-content: center;
    align-items: center;

    .onlineDot {
      background: rgba(49, 192, 46, 0.8);
      width: 10px;
      height: 10px;
      margin: 0px 5px 0px 10px;
      border-radius: 50%;
      display: inline-block;
      box-shadow: 0px 0px 0px 4px rgba(49, 192, 46, 0.4);
    }
  }

  .currentLobby {
    margin-right: 20px;
  }

  .item {
    color: rgba(177, 177, 177, 0.7);
  }

  .timeDate {
    display: flex;
    justify-content: center;
    align-items: center;
    margin: 0px 20px 0px 0px;

    i {
      font-size: 20px;
      margin-right: 8px;
    }
  }

  .logo {
    width: 40px;
    height: 40px;
  }
}

</style>