<template>
  <div class="wrapper">
    <div class="top">
      Lobbies
    </div>
    <div class="bottom">
      <div class="lobbies">
        <div v-for="lobby in lobbies" :key="lobby.id" :class="['lobby']"
             :style="{ background: 'linear-gradient(rgba(25, 23, 36, 0.9),rgba(25, 23, 36, 0.9)),  url(' + lobby.background + ') no-repeat center center', backgroundSize: 'cover' }">
          <div class="info">
            <div class="lobby-name">{{ lobby.name }}<i v-show="lobby.password" class='bx bx-lock-alt lobby-locked' ></i></div>
            <div class="lobby-info">
              <div v-show="lobby.gamemode" class="lobby-gamemode">{{ lobby.gamemode }}</div>
              <div v-show="lobby.description" class="lobby-description">{{ lobby.description }}</div>
            </div>
          </div>
          <div class="players">
            <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span><i class="fas fa-users"></i>
          </div>
          <div class="join">
            <button :class="['join-button', { full: lobby.players === lobby.maxplayers }]"
                    @click="joinParty(lobby.id, lobby.name, lobby.players, lobby.maxplayers, lobby.password)">
              <div v-if="lobby.players === lobby.maxplayers">Full</div>
              <div v-else>Join</div>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "LobbiesTab",
  methods: {
    joinParty(id, name, players, maxplayers, password = null) {

      if (players >= maxplayers) {
        iziToast.show({
          message: `Lobby <strong>${name}</strong> is full.`,
          color: 'red',
          icon: 'fas fa-users-slash',
          close: false,
          timeout: 1000,
        });
        return;
      }

      if (!password) {
        mp.trigger('PutPlayerInLobby', id);
        iziToast.show({
          message: `Joined <strong>${name} (${id})</strong>`,
          color: 'blue',
          icon: 'fas fa-users',
          close: false,
          timeout: 1000,
        });
        return;
      }

      Swal.fire({
        title: 'Lobby Password',
        input: 'password',
        inputAttributes: {
          autocapitalize: 'off'
        },
        showCancelButton: true,
        confirmButtonText: 'Join',
        buttonsStyling: false,
        customClass: {
          confirmButton: 'lobby-pass-confirm',
          cancelButton: 'lobby-pass-cancel',
          input: 'lobby-pass-input',
        },
      }).then((result) => {
        if (result.isConfirmed) {
          if (result.value === password) {
            mp.trigger('PutPlayerInLobby', id);
            iziToast.show({
              message: `Joined <strong>${name} (${id})</strong>`,
              color: 'blue',
              icon: 'fas fa-users',
              close: false,
              timeout: 1000,
            });
          } else {
            iziToast.show({
              message: `Invalid password.`,
              color: 'red',
              icon: 'fas fa-lock',
              close: false,
              timeout: 1000,
            });
          }
        }
      })
    }
  },
  data() {
    return {
      lobbies: [{
        id: 0,
        name: 'Copchase 1',
        background: 'https://live.staticflickr.com/7526/16232917915_3ef3d4ab4d_b.jpg',
        gamemode: 'Copchase',
        password: 'sex',
        players: 11,
        maxplayers: 25
      }, {
        id: 1,
        name: 'Copchase 2',
        description: 'Optional description',
        background: 'https://wallpapercave.com/wp/wp4501529.jpg',
        gamemode: 'Copchase',
        players: 14,
        maxplayers: 35
      }, {
        id: 2,
        name: 'Copchase 3',
        background: 'https://wallpapers-hub.art/wallpaper-images/192181.jpg',
        gamemode: 'Copchase',
        players: 8,
        maxplayers: 20
      }, {
        id: 3,
        name: 'Copchase 4',
        background: 'https://c4.wallpaperflare.com/wallpaper/519/763/782/gta-5-background-desktop-wallpaper-preview.jpg',
        gamemode: 'Copchase',
        players: 15,
        maxplayers: 15
      }, {
        id: 3,
        name: 'Copchase 5',
        background: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQaX9re0Ofp-nbJHKtv0FyaKlz5KQsOeP9doxhHDwCrEYkdpV8FDWKIo_gLqVc4JNGDHHs&usqp=CAU',
        gamemode: 'Copchase',
        players: 0,
        maxplayers: 10
      },]
    }
  }
}
</script>

<style scoped lang="scss">
.lobby-locked {
  color: $sago-gray2;
  font-size: 25px;
  margin-left: 10px;
}

.lobby-pass-confirm {
  background: none;
  border: 2px solid #2d6ae3;
  color: #f1f1f1;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-right: 10px;
  font-weight: bold;

  &:hover {
    background: #2d6ae3;
  }

  &:focus {
    border: 2px solid #2d6ae3;
    outline: none;
    background: #2d6ae3;
  }
}

.lobby-pass-cancel {
  background: none;
  border: 2px solid $sago-gray;
  color: $sago-gray;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-left: 10px;
  font-weight: bold;

  &:hover {
    background: $sago-gray;
    color: #fff;
  }

  &:focus {
    border: 2px solid $sago-gray;
    outline: none;
    background: $sago-gray;
    color: #fff;
  }
}

.lobby-pass-input {
  border: none !important;
  border-radius: 0px !important;
}

/* width */
::-webkit-scrollbar {
  width: 7px;
}

/* Track */
::-webkit-scrollbar-track {
  background: none;
}

/* Handle */
::-webkit-scrollbar-thumb {
  background: $lscc-blue;
}

.wrapper {
  display: flex;
  flex-direction: column;
}

.top {
  height: 50px;
  display: flex;
  align-items: center;
  padding: 20px 0px 20px 30px;
  font-size: 22px;
  color: #fff;
}

.lobbies {
  display: grid;
  grid-template-columns: 50% 50%;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
