}

.lobby {
  display: flex;
  border: 2px solid $sago-dark;
  height: 130px;
  margin: 10px 10px;

  .info {
    flex: 0.6;
    display: grid;
    padding: 10px 0px 0px 30px;
    color: #fff;
    font-weight: 300;
  }

  .lobby-name {
    color: #fff;
    font-size: 25px;
    font-weight: 300;
  }

  .players {
    flex: 0.3;
    font-size: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;

    .lobby-stats {
      margin-right: 7px;
      font-weight: 300;
    }

    .fas {
      color: $sago-gray2;
      font-size: 25px;
    }
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .join-button {
    background: none;
    border: 2px solid #2d6ae3;
    color: #fff;
    padding: 10px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;

    &:hover {
      background: #2d6ae3;
    }
  }

  .full {
    border: 2px solid $sago-gray2;
    color: $sago-gray2;
    cursor: default;

    &:hover {
      background: none;
    }
  }
}
</style>