<template>
  <div class="wrap">
    <div class="top">
      <Dropdown v-model="selectedType" class="mr-2" :options="types" optionLabel="name" placeholder="Select a Type"/>
      <AutoComplete v-model="selectedPlayer" :suggestions="filteredPlayers" @complete="searchPlayer($event)"
                    field="name"/>
      <Button type="button" class="h-3rem w-3rem ml-2" icon="pi pi-search" :loading="searchLoading" @click="getData()"/>
    </div>
    <div class="bottom">
      <DataTable style="min-height:400px" :paginator="true" :rows="6" class="p-2 pb-8" :value="logsData"
                 :scrollable="true" scrollHeight="400px">
        <Column :sortable="true" v-for="col of logsColumns" :field="col.field" :header="col.header"
                :key="col.field"></Column>
      </DataTable>
    </div>
  </div>
</template>

<script>
import Dropdown from 'primevue/dropdown';
import AutoComplete from 'primevue/autocomplete';
import Button from 'primevue/button';

import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import ColumnGroup from 'primevue/columngroup';     //optional for column grouping

export default {
  name: "LogsMenu",
  components: {
    Dropdown, AutoComplete, Button, DataTable, Column, ColumnGroup
  },
  data() {
    return {
      searchLoading: false,
      players: [{name: 'Nigga'}, {name: 'Peder'}, {name: 'SWAT'}, {name: 'Dragan'}, {name: 'LSCC'}, {name: 'SAPP'}],
      selectedPlayer: null,
      filteredPlayers: null,
      selectedType: {name: 'Admin'},
      types: [
        {name: 'Admin'},
        {name: 'Session'},
      ],
      logsColumns: [
        {field: 'type', header: 'Type'},
        {field: 'reason', header: 'Reason'},
        {field: 'timestamp', header: 'Timestamp'},
        {field: 'duration', header: 'Duration'}
      ],
      //logsColumns: ["Type", "Reason", "Timestamp", "Duration"],
      logsData: [
        {"type": "Warn", "reason": "Nez poy", "timestamp": "1/1/1923", "duration": "N/A"},
        {"type": "Ban", "reason": "EZ", "timestamp": "3/2/2323", "duration": "N/A"},
        {"type": "Jail", "reason": "Kampa na ljestvama", "timestamp": "2/3/2302", "duration": "30 minutes"},
        {"type": "Kick", "reason": "Mnogo sere u voice chat", "timestamp": "3/1/2032", "duration": "N/A"},
      ]
    }
  },
  methods: {
    getData() {
      this.searchLoading = true;
      setTimeout(() => this.searchLoading = false, 1000);
    },
    searchPlayer(event) {
      this.filteredPlayers = this.players.filter(p => p.name.toLowerCase().includes(event.query.toLowerCase()));
    }
  },
}
</script>

