<template>
    <div class="window">
      <div class="window-header">
        <div class="window-title">{{ title }}</div>
        <div class="window-close"><i @click="$emit('update:show', false)" class="fas fa-times-circle"></i></div>
      </div>
      <div class="window-body">
        <slot></slot>
      </div>
    </div>
</template>

<script>
const draggable = require('jquery-ui/ui/widgets/draggable');
export default {
  name: "Window",
  props: ['title', 'show'],
  emits: ['update:show'],
  methods: {
    close() {
      console.log('sus');
      console.log(this.show);
      this.show = false;
    }
  },
  mounted() {
    $(function () {
      $(".window").draggable({ handle: ".window-header" });
    });
  }
}
</script>

<style scoped lang="scss">

.window {
  background: $sago-darkest;
  border-radius: 5px;

  .window-header {
    background: $sago-darker;
    padding: 2px 5px 2px 5px;
    color: $sago-gray;
    font-weight: bold;
    display: flex;
    align-items: center;

    .window-close {
      display: flex;
      justify-content: flex-end;
      align-items: center;
      font-size: 18px;
      margin-left: 5px;
      flex: 1;

      i {
        cursor: pointer;
      }
    }
  }
}
</style>